"use client";

/**
 * FolderTray
 *
 * An interactive 3D isometric tray of folders with kinematic spring lean physics.
 * Built on top of and inspired by Lucas Markes' hairline riffle engine:
 * https://github.com/lucasmarkes/hairline
 */

import React, { useState, useEffect, useRef, useCallback } from "react";
import { Riffle } from "@lucasmarkes/hairline/react";
export { Folder, type FolderProps } from "./folder";

export interface FolderItem<T = unknown> {
  id: string;
  name: string;
  /** Optional URL destination. If provided, clicking can navigate to this link. */
  href?: string;
  /** Target window/frame for navigation (e.g. "_blank", "_self") */
  target?: "_blank" | "_self" | string;
  /** Fill / background color for the body of the folder (e.g. "#FFFFFF", "#FFF7ED") */
  bodyColor?: string;
  /** Dark outline color for silhouette, tab headline, and active punch dot (e.g. "#232327", "#E54F10") */
  darkOutline?: string;
  /** Light outline color for 5 ruled lines, back face, and inactive punch dots (e.g. "#E0E0E4", "#FDBA74") */
  lightOutline?: string;

  /** Alias for bodyColor */
  color?: string;
  /** Alias for bodyColor */
  fill?: string;
  /** Alias for darkOutline */
  outline?: string;

  category?: string;
  description?: string;
  /** Custom rich content, article, or notes to render when viewing this folder */
  content?: React.ReactNode;
  badge?: string;
  data?: T;
}

export interface FolderTrayProps<T = unknown> {
  /** Array of folder cards (1 to 8). Each folder defines bodyColor, darkOutline, and lightOutline. */
  folders: FolderItem<T>[];
  /** Visual theme variant: "color" for vibrant colored folders, "original" for clean monochrome white line-art (default: "color") */
  variant?: "color" | "original";
  /** Default body color (default: "#E461F5") */
  defaultBodyColor?: string;
  /** Default dark outline (default: "#C137D5") */
  defaultDarkOutline?: string;
  /** Default light outline (default: "#F9D8FD") */
  defaultLightOutline?: string;
  /** Callback triggered when a folder is clicked */
  onOpen?: (folder: FolderItem<T>) => void;
  /** Callback triggered when active folder selection changes */
  onSelect?: (folder: FolderItem<T>) => void;
  /** Callback triggered when a folder is hovered or scrubbed over */
  onHover?: (folder: FolderItem<T> | null) => void;
  /** Initial selected folder index */
  defaultSelected?: number;
  /** Spring intensity from 0 to 1 (default: 0.65) */
  intensity?: number;
  className?: string;
  style?: React.CSSProperties;
}

export function FolderTray<T = unknown>({
  folders,
  variant = "color",
  defaultBodyColor = "#E461F5",
  defaultDarkOutline = "#C137D5",
  defaultLightOutline = "#F9D8FD",
  onOpen,
  onSelect,
  onHover,
  defaultSelected = 0,
  intensity = 0.65,
  className = "",
  style,
}: FolderTrayProps<T>) {
  const [selectedIndex, setSelectedIndex] = useState(defaultSelected);
  const [hoverIndex, setHoverIndex] = useState<number | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const lastReportedCard = useRef<number | null>(null);

  const isOriginal = variant === "original";

  const getFolderItem = useCallback(
    (idx: number): FolderItem<T> | undefined => {
      const folder = folders[idx];
      if (!folder) return undefined;
      if (!isOriginal) return folder;
      return {
        ...folder,
        bodyColor: "#FFFFFF",
        darkOutline: "#232327",
        lightOutline: "#E0E0E4",
      };
    },
    [folders, isOriginal]
  );

  const activeFolder = getFolderItem(selectedIndex) || getFolderItem(0);
  const displayedFolder =
    hoverIndex !== null ? getFolderItem(hoverIndex) || activeFolder : activeFolder;

  const triggerCardAction = useCallback(
    (f: FolderItem<T>, e?: MouseEvent | React.MouseEvent) => {
      onSelect?.(f);
      if (onOpen) {
        onOpen(f);
      } else if (f.href) {
        const target = f.target || "_blank";
        if (target === "_blank" || e?.metaKey || e?.ctrlKey) {
          window.open(f.href, "_blank", "noopener,noreferrer");
        } else {
          window.location.href = f.href;
        }
      }
    },
    [onOpen, onSelect]
  );

  // Set card indexes and attach click listeners to the SVG card groups
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let observer: MutationObserver | null = null;
    let cancelled = false;

    const setupCards = () => {
      if (cancelled) return false;
      const stage = container.querySelector('[data-hairline="riffle"]');
      if (!stage) return false;

      // Filter specifically for card groups containing path.sil (excludes the tray reflection ghost)
      const allGroups = stage.querySelectorAll("svg > g > g");
      const cardGroups = Array.from(allGroups).filter((g) => g.querySelector("path.sil"));
      if (cardGroups.length === 0) return false;

      cardGroups.forEach((grp, idx) => {
        const item = folders[idx];
        const body = isOriginal
          ? "#FFFFFF"
          : item?.bodyColor || item?.fill || item?.color || defaultBodyColor;
        const dark = isOriginal
          ? "#232327"
          : item?.darkOutline || item?.outline || defaultDarkOutline;
        const light = isOriginal ? "#E0E0E4" : item?.lightOutline || defaultLightOutline;

        const grpEl = grp as HTMLElement;
        grpEl.setAttribute("data-card-index", String(idx));
        grpEl.style.cursor = "pointer";
        grpEl.style.setProperty("--folder-body", body);
        grpEl.style.setProperty("--folder-dark", dark);
        grpEl.style.setProperty("--folder-light", light);

        if (idx === selectedIndex) {
          grpEl.setAttribute("data-selected", "true");
        } else {
          grpEl.removeAttribute("data-selected");
        }

        // Attach click listener
        grpEl.onclick = (e) => {
          e.stopPropagation();
          setSelectedIndex(idx);
          const f = getFolderItem(idx);
          if (f) {
            triggerCardAction(f, e);
          }
        };
      });

      return cardGroups.length >= 8;
    };

    // Try immediately
    if (!setupCards()) {
      observer = new MutationObserver(() => {
        if (setupCards() && observer) {
          observer.disconnect();
          observer = null;
        }
      });
      observer.observe(container, { childList: true, subtree: true });

      const t1 = setTimeout(setupCards, 30);
      const t2 = setTimeout(setupCards, 80);
      const t3 = setTimeout(setupCards, 200);
      const t4 = setTimeout(setupCards, 500);

      return () => {
        cancelled = true;
        observer?.disconnect();
        clearTimeout(t1);
        clearTimeout(t2);
        clearTimeout(t3);
        clearTimeout(t4);
      };
    }

    return () => {
      cancelled = true;
      observer?.disconnect();
    };
  }, [
    folders,
    getFolderItem,
    selectedIndex,
    triggerCardAction,
    isOriginal,
    defaultBodyColor,
    defaultDarkOutline,
    defaultLightOutline,
  ]);

  // Smooth throttled onRead: only update hover index when crossing between distinct folders
  const handleRead = useCallback(
    (label: string) => {
      let cardIdx: number | null = null;
      if (label && label !== "rest") {
        const punchNum = parseInt(label, 10);
        if (!isNaN(punchNum) && punchNum >= 1 && punchNum <= 8) {
          cardIdx = 8 - punchNum;
        }
      }

      if (lastReportedCard.current !== cardIdx) {
        lastReportedCard.current = cardIdx;
        setHoverIndex(cardIdx);
        const hovered = cardIdx !== null ? getFolderItem(cardIdx) || null : null;
        onHover?.(hovered);
      }
    },
    [getFolderItem, onHover]
  );

  const handleContainerClick = (e: React.MouseEvent) => {
    // Only open if clicking on an actual folder card
    if (lastReportedCard.current === null) {
      return;
    }

    const target = e.target as HTMLElement | SVGElement | null;
    const cardEl = target?.closest?.("[data-card-index]");
    if (!cardEl) {
      return;
    }

    const cardIndexAttr = cardEl.getAttribute("data-card-index");
    const targetIdx =
      cardIndexAttr !== null && cardIndexAttr !== undefined
        ? parseInt(cardIndexAttr, 10)
        : lastReportedCard.current;

    if (targetIdx !== null) {
      const f = getFolderItem(targetIdx);
      if (f) {
        setSelectedIndex(targetIdx);
        triggerCardAction(f, e);
      }
    }
  };

  const handleContainerLeave = () => {
    lastReportedCard.current = null;
    setHoverIndex(null);
    onHover?.(null);
  };

  // Build 3 distinct CSS color variables for each folder (body, dark outline, light outline)
  const cssColorVariables: Record<string, string> = {};
  folders.slice(0, 8).forEach((item, idx) => {
    const body = isOriginal
      ? "#FFFFFF"
      : item.bodyColor || item.fill || item.color || defaultBodyColor;
    const dark = isOriginal ? "#232327" : item.darkOutline || item.outline || defaultDarkOutline;
    const light = isOriginal ? "#E0E0E4" : item.lightOutline || defaultLightOutline;

    cssColorVariables[`--folder-body-${idx}`] = body;
    cssColorVariables[`--folder-dark-${idx}`] = dark;
    cssColorVariables[`--folder-light-${idx}`] = light;
  });

  return (
    <div
      className={`folder-tray relative aspect-[5/4] w-full max-w-[460px] select-none [&_[data-card-index]_path.sil]:![fill:var(--folder-body,#fff)] [&_[data-card-index]_path.sil]:![stroke:var(--folder-dark,#232327)] [&_[data-card-index]_path.lo:not(.nf)]:![fill:var(--folder-body,#fff)] [&_[data-card-index]_path.lo:not(.nf)]:![stroke:var(--folder-light,#e0e0e4)] [&_[data-card-index]_path.nf:not(.lo)]:![fill:none] [&_[data-card-index]_path.nf:not(.lo)]:![stroke:var(--folder-dark,#232327)] [&_[data-card-index]_path.nf.lo]:![fill:none] [&_[data-card-index]_path.nf.lo]:![stroke:var(--folder-light,#e0e0e4)] [&_[data-card-index]_circle.dot]:![stroke:none] [&_[data-card-index]_circle.dot]:![fill:var(--folder-dark,#232327)] [&_[data-card-index]_circle.dot.off]:![fill:var(--folder-light,#e0e0e4)] [&_[data-card-index]_circle.dot.m]:![fill:var(--folder-dark,#232327)] ${className}`}
      style={{ ...(style || {}), ...cssColorVariables } as React.CSSProperties}
    >
      {/* 3D Isometric Folder Tray Container */}
      <div
        ref={containerRef}
        onClick={handleContainerClick}
        onMouseLeave={handleContainerLeave}
        className={`h-full w-full ${hoverIndex !== null ? "cursor-pointer" : "cursor-default"}`}
        title={
          hoverIndex !== null && displayedFolder
            ? displayedFolder.href
              ? `Open link: ${displayedFolder.name} ↗`
              : `View: ${displayedFolder.name}`
            : undefined
        }
      >
        <Riffle
          intensity={intensity}
          theme="light"
          onRead={handleRead}
          style={{ width: "100%", height: "100%" }}
        />
      </div>
    </div>
  );
}

"use client";

/**
 * Folder
 *
 * Standalone forward-facing 2D vector folder with exact 84x61 proportions, filleted tabs,
 * and punch dots. Silhouette geometry and fillet algorithms adapted from Lucas Markes' hairline:
 * https://github.com/lucasmarkes/hairline
 */

import React from "react";

export interface FolderProps {
  bodyColor?: string;
  darkOutline?: string;
  lightOutline?: string;
  borderWidth?: number | string; // Thickness of the silhouette outline and divider lines (e.g. 1.2, 1, or "1px")
  depth?: boolean | number; // 3D cardstock thickness with offset back face (default: true)
  folderIndex?: number; // 0 to 7 to determine exact tab position and active punch dot
  tabPosition?: "left" | "center" | "right";
  showLines?: boolean; // Set to false to hide the 4 horizontal ruled lines
  className?: string;
  children?: React.ReactNode;
}

// Geometric constants matching @lucasmarkes/hairline riffle-geometry.ts
const W = 84;
const H = 54;
const TW = 22;
const TH = 7;
const TOTAL_H = H + TH + 1; // 62
const TABS = [6, 31, 56]; // Left, Center, Right

function fillet(pts: [number, number][], rs: number[], n = 4): [number, number][] {
  const m = pts.length;
  const out: [number, number][] = [];
  for (let i = 0; i < m; i++) {
    const a = pts[(i + m - 1) % m];
    const p = pts[i];
    const b = pts[(i + 1) % m];
    const la = Math.hypot(a[0] - p[0], a[1] - p[1]);
    const lb = Math.hypot(b[0] - p[0], b[1] - p[1]);
    const t = Math.min(rs[i], la / 2, lb / 2);
    const p1: [number, number] = [p[0] + ((a[0] - p[0]) / la) * t, p[1] + ((a[1] - p[1]) / la) * t];
    const p2: [number, number] = [p[0] + ((b[0] - p[0]) / lb) * t, p[1] + ((b[1] - p[1]) / lb) * t];
    for (let k = 0; k <= n; k++) {
      const s = k / n;
      const w = 1 - s;
      out.push([
        w * w * p1[0] + 2 * w * s * p[0] + s * s * p2[0],
        w * w * p1[1] + 2 * w * s * p[1] + s * s * p2[1],
      ]);
    }
  }
  return out;
}

const r2 = (x: number) => Math.round(x * 100) / 100;
const toSvgPath = (pts: [number, number][]) =>
  "M" + pts.map((p) => r2(p[0]) + " " + r2(p[1])).join("L") + "Z";

function generateFolderSilhouette(t0: number): string {
  const rawPts = fillet(
    [
      [0, 0],
      [W, 0],
      [W, H],
      [t0 + TW, H],
      [t0 + TW, H + TH],
      [t0, H + TH],
      [t0, H],
      [0, H],
    ],
    [1, 1, 3.2, 1.8, 2.4, 2.4, 1.8, 3.2]
  );
  // Invert Y so the tab is at the top in SVG
  const pts: [number, number][] = rawPts.map(([x, y]) => [x, TOTAL_H - y]);
  return toSvgPath(pts);
}

// Pre-computed silhouette paths for each tab position (Left = 0, Center = 1, Right = 2)
const SILHOUETTES = [
  generateFolderSilhouette(TABS[0]),
  generateFolderSilhouette(TABS[1]),
  generateFolderSilhouette(TABS[2]),
];

/**
 * Folder
 * Renders a folder card facing forward in 2D vector format,
 * using geometric vector paths, tab fillets, ruled lines, and punch dots.
 */
export function Folder({
  bodyColor = "#E461F5",
  darkOutline = "#C137D5",
  lightOutline = "#F9D8FD",
  borderWidth = 1.2,
  depth = true,
  folderIndex = 0,
  tabPosition,
  showLines = true,
  className = "w-44 h-auto drop-shadow-sm",
  children,
}: FolderProps) {
  // Determine tab index: 0 = left, 1 = center, 2 = right
  let tabIdx = 1;
  if (tabPosition === "left") tabIdx = 0;
  else if (tabPosition === "center") tabIdx = 1;
  else if (tabPosition === "right") tabIdx = 2;
  else {
    // Matches tab cycle: t0 = TABS[(8 - 1 - i) % 3]
    tabIdx = (7 - (folderIndex % 8)) % 3;
  }

  const t0 = TABS[tabIdx];
  const silhouettePath = SILHOUETTES[tabIdx];
  // Active dot index matching hairline (k === n - 1 where n = 8 - i)
  const activeDotIndex = 7 - (folderIndex % 8);

  const dividerStrokeWidth =
    typeof borderWidth === "number" ? Math.max(0.75, borderWidth * 0.75) : borderWidth;

  // 3D cardstock thickness offset (back face shifted up and to the right)
  const depthValue = typeof depth === "number" ? depth : depth ? 1 : 0;
  const depthOffsetX = depthValue * 0.95;
  const depthOffsetY = -depthValue * 0.95;

  const svgContent = (
    <svg
      viewBox={depthValue > 0 ? "-2 -2 89 66" : "-2 -1 88 65"}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={children ? "h-full w-full" : className}
    >
      {/* 0. 3D Back Face (Cardstock Thickness Bevel with Light Outline) */}
      {depthValue > 0 && (
        <path
          d={silhouettePath}
          transform={`translate(${depthOffsetX}, ${depthOffsetY})`}
          fill={bodyColor}
          stroke={lightOutline}
          strokeWidth={borderWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinejoin="round"
        />
      )}

      {/* 1. Main Folder Silhouette Face (Front Face with Dark Outline) */}
      <path
        d={silhouettePath}
        fill={bodyColor}
        stroke={darkOutline}
        strokeWidth={borderWidth}
        vectorEffect="non-scaling-stroke"
        strokeLinejoin="round"
      />

      {/* 2. Top Header Divider Line below the tab */}
      {showLines && (
        <line
          x1="6"
          y1="19"
          x2="78"
          y2="19"
          stroke={darkOutline}
          strokeWidth={dividerStrokeWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinecap="round"
        />
      )}

      {/* 3. Four Horizontal Ruled Lines */}
      {showLines &&
        [26, 33, 40, 47].map((y) => (
          <line
            key={y}
            x1="6"
            y1={y}
            x2="78"
            y2={y}
            stroke={lightOutline}
            strokeWidth={dividerStrokeWidth}
            vectorEffect="non-scaling-stroke"
            strokeLinecap="round"
          />
        ))}

      {/* 4. Eight Punch Dots on the Tab (2 rows of 4) */}
      {Array.from({ length: 8 }).map((_, k) => {
        const cx = t0 + TW / 2 + ((k % 4) - 1.5) * 3.6;
        const cy = Math.floor(k / 4) === 0 ? 3.2 : 5.8;
        const isActive = k === activeDotIndex;

        return (
          <circle
            key={k}
            cx={cx}
            cy={cy}
            r={1.05}
            fill={isActive ? darkOutline : lightOutline}
            stroke="none"
          />
        );
      })}
    </svg>
  );

  if (!children) {
    return svgContent;
  }

  return (
    <div className={`relative ${className}`}>
      {svgContent}
      <div className="absolute inset-0 flex flex-col">{children}</div>
    </div>
  );
}

"use client";

