 * and punch dots. Silhouette geometry and fillet algorithms adapted from Lucas Markes' hairline:
 * https://github.com/lucasmarkes/hairline
 */

import React from "react";

export interface FolderProps {
  bodyColor?: string;
  darkOutline?: string;
  lightOutline?: string;
  borderWidth?: number | string; // Thickness of the silhouette outline and divider lines (e.g. 1.2, 1, or "1px")
  depth?: boolean | number; // 3D cardstock thickness with offset back face (default: true)
