export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  depth?: string;
  radius?: string;
  faceColor?: string;
  faceHighlight?: string;
  contentColor?: string;
  baseColor?: string;
  baseShadow?: string;
  href?: string;
  target?: string;
  rel?: string;
  children: React.ReactNode;
}

const VARIANTS = {
  default: {
    face: "#4a4a46",
    highlight: "#64645e",
    content: "#eeeeec",
    base: "#292926",
    shadow: "#141412",
  },
  dark: {
    face: "#1e2024",
    highlight: "#353840",
    content: "#ffffff",
    base: "#111215",
    shadow: "#09090b",
